"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { Check, ClipboardList, Eye, Loader2, Users, X } from "lucide-react";
import Navbar from "@/components/Navbar";
import Sidebar from "@/components/Sidebar";
import { api } from "@/lib/api";

type AppStatus = "PENDING" | "ACCEPTED" | "REJECTED" | "COMPLETED";
type Application = { id: string; projectId: string; projectTitle: string; roleTitle: string; applicationStatus: AppStatus; appliedAt?: string; applicant?: { userId?: string; fullName?: string; major?: string; email?: string; skills?: Array<{ skillName?: string; rankTier?: string }> } };
type Quest = { id: string; title: string; description?: string; status: "OPEN" | "IN_PROGRESS" | "COMPLETED"; createdAt?: string; owner?: { id?: string }; roles?: unknown[] };
const statusStyle: Record<AppStatus, string> = { PENDING: "bg-amber-400/15 text-amber-700 dark:text-amber-300", ACCEPTED: "bg-[#3ecf8e]/15 text-[#21875c] dark:text-[#3ecf8e]", REJECTED: "bg-rose-500/15 text-rose-700 dark:text-rose-300", COMPLETED: "bg-purple-500/15 text-purple-700 dark:text-purple-300" };

export default function MyQuestsPage() {
  const [sidebarOpen, setSidebarOpen] = useState(false); const [tab, setTab] = useState<"posted" | "applied">("posted"); const [posted, setPosted] = useState<Quest[]>([]); const [applied, setApplied] = useState<Application[]>([]); const [selectedQuest, setSelectedQuest] = useState<Quest | null>(null); const [applicants, setApplicants] = useState<Application[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  const load = async () => { setLoading(true); setError(""); try { const [profile, projects, applications] = await Promise.all([api.profiles.getMe(), api.projects.list(), api.applications.getMyApplications()]); setPosted((projects as Quest[]).filter((quest) => quest.owner?.id === profile?.userId)); setApplied(applications as Application[]); } catch { setError("Quest management is unavailable until you sign in to the SideQuest backend."); } finally { setLoading(false); } };
  useEffect(() => { load(); }, []);
  const openApplicants = async (quest: Quest) => { setSelectedQuest(quest); setApplicants([]); try { setApplicants(await api.projects.getApplications(quest.id) as Application[]); } catch { setError("Unable to load applicants for this quest."); } };
  const decide = async (application: Application, status: "ACCEPTED" | "REJECTED") => { try { await api.applications.updateStatus(application.id, status); setApplicants((current) => current.map((item) => item.id === application.id ? { ...item, applicationStatus: status } : item)); if (status === "ACCEPTED" && selectedQuest) setPosted((current) => current.map((quest) => quest.id === selectedQuest.id ? { ...quest, status: "IN_PROGRESS" } : quest)); } catch { setError("Unable to update this application. Please try again."); } };
  const withdraw = async (application: Application) => { try { await api.applications.updateStatus(application.id, "REJECTED"); setApplied((current) => current.map((item) => item.id === application.id ? { ...item, applicationStatus: "REJECTED" } : item)); } catch { setError("Unable to withdraw this application."); } };
  const counts = useMemo(() => applicants.reduce((total, application) => total + (application.applicationStatus === "PENDING" ? 1 : 0), 0), [applicants]);
  return <div className="min-h-screen bg-[#f8fafc] text-slate-900 dark:bg-[#121212] dark:text-[#ededed]"><Navbar onToggleSidebar={() => setSidebarOpen((open) => !open)} /><div className="flex"><Sidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} /><main className="min-h-[calc(100vh-3.5rem)] w-full lg:pl-64"><div className="mx-auto max-w-5xl space-y-6 px-4 py-6 sm:px-6"><header className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 pb-4 dark:border-[#282828]"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#3ecf8e]/10 text-[#21875c] dark:text-[#3ecf8e]"><ClipboardList className="h-4 w-4" /></div><div><h1 className="text-xl font-bold">My Quests</h1><p className="text-xs text-slate-500 dark:text-zinc-400">Review applicant decisions and track your submitted applications.</p></div></div><div role="tablist" className="flex rounded-lg border border-slate-200 bg-slate-50 p-1 dark:border-[#383838] dark:bg-[#161616]"><button type="button" onClick={() => setTab("posted")} className={`rounded-md px-3 py-1.5 text-xs font-semibold ${tab === "posted" ? "bg-[#3ecf8e] text-[#042f1a] shadow-sm" : "text-slate-500 dark:text-zinc-400"}`}>Posted Quests</button><button type="button" onClick={() => setTab("applied")} className={`rounded-md px-3 py-1.5 text-xs font-semibold ${tab === "applied" ? "bg-[#3ecf8e] text-[#042f1a] shadow-sm" : "text-slate-500 dark:text-zinc-400"}`}>Applied Quests</button></div></header>{error && <p className="rounded-lg border border-amber-400/30 bg-amber-400/10 px-3 py-2 text-xs text-amber-700 dark:text-amber-300">{error}</p>}{loading ? <div className="flex justify-center py-16"><Loader2 className="h-6 w-6 animate-spin text-[#3ecf8e]" /></div> : tab === "posted" ? <div className="space-y-3">{posted.length ? posted.map((quest) => <article key={quest.id} className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm dark:border-[#282828] dark:bg-[#1c1c1c]"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><h2 className="break-words text-sm font-semibold">{quest.title}</h2><p className="mt-1 text-xs text-slate-500 dark:text-zinc-400">Created {quest.createdAt ? new Date(quest.createdAt).toLocaleDateString() : "recently"} · {quest.roles?.length || 0} roles</p></div><span className="rounded-full bg-sky-500/10 px-2.5 py-1 text-[10px] font-bold text-sky-700 dark:text-sky-300">{quest.status.replace("_", " ")}</span></div><button type="button" onClick={() => openApplicants(quest)} className="mt-4 inline-flex items-center gap-1.5 rounded-lg bg-[#3ecf8e] px-3 py-2 text-xs font-semibold text-[#042f1a]"><Users className="h-3.5 w-3.5" />View Applicants</button></article>) : <Empty text="You have not posted any quests yet." />}</div> : <div className="space-y-3">{applied.length ? applied.map((application) => <article key={application.id} className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm dark:border-[#282828] dark:bg-[#1c1c1c]"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-sm font-semibold">{application.projectTitle}</h2><p className="mt-1 text-xs text-slate-500 dark:text-zinc-400">Applied for {application.roleTitle} · {application.appliedAt ? new Date(application.appliedAt).toLocaleDateString() : "recently"}</p></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${statusStyle[application.applicationStatus]}`}>{application.applicationStatus}</span></div><div className="mt-4 flex flex-wrap gap-2"><Link href={`/quests`} className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold dark:border-[#383838]"><Eye className="h-3.5 w-3.5" />View quest</Link>{application.applicationStatus === "PENDING" && <button type="button" onClick={() => withdraw(application)} className="rounded-lg border border-rose-300 px-3 py-2 text-xs font-semibold text-rose-600 dark:border-rose-900 dark:text-rose-300">Withdraw application</button>}</div></article>) : <Empty text="You have not applied to any quests yet." />}</div>}{selectedQuest && <ApplicantModal quest={selectedQuest} applicants={applicants} pending={counts} onClose={() => setSelectedQuest(null)} onDecide={decide} />}</div></main></div></div>;
}

function Empty({ text }: { text: string }) { return <div className="rounded-xl border border-dashed border-slate-200 bg-white px-5 py-16 text-center text-sm text-slate-500 dark:border-[#383838] dark:bg-[#1c1c1c] dark:text-zinc-400">{text}</div>; }
function ApplicantModal({ quest, applicants, pending, onClose, onDecide }: { quest: Quest; applicants: Application[]; pending: number; onClose: () => void; onDecide: (application: Application, status: "ACCEPTED" | "REJECTED") => void }) { return <div className="fixed inset-0 z-50 flex justify-end bg-black/50" onClick={onClose}><aside onClick={(event) => event.stopPropagation()} className="h-full w-full max-w-xl overflow-y-auto bg-white p-5 shadow-2xl dark:bg-[#1c1c1c] sm:p-6"><div className="flex items-start justify-between gap-3 border-b border-slate-200 pb-4 dark:border-[#282828]"><div><h2 className="text-base font-semibold">Applicants</h2><p className="mt-1 text-xs text-slate-500 dark:text-zinc-400">{quest.title} · {pending} pending</p></div><button type="button" onClick={onClose} className="rounded-lg p-1 text-slate-500 hover:bg-slate-100 dark:hover:bg-[#282828]"><X className="h-5 w-5" /></button></div><div className="mt-4 space-y-3">{applicants.length ? applicants.map((application) => <article key={application.id} className="rounded-xl border border-slate-200 p-4 dark:border-[#383838]"><div className="flex gap-3"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#3ecf8e]/15 text-xs font-bold text-[#21875c] dark:text-[#3ecf8e]">{(application.applicant?.fullName || "A").slice(0, 1)}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="text-sm font-semibold">{application.applicant?.fullName || application.applicant?.email || "Applicant"}</h3><span className={`rounded-full px-2 py-0.5 text-[9px] font-bold ${statusStyle[application.applicationStatus]}`}>{application.applicationStatus}</span></div><p className="mt-1 text-xs text-slate-500 dark:text-zinc-400">{application.applicant?.major || "Campus builder"}</p><div className="mt-2 flex flex-wrap gap-1">{application.applicant?.skills?.slice(0, 4).map((skill, index) => <span key={`${skill.skillName}-${index}`} className="rounded bg-slate-100 px-2 py-0.5 text-[10px] dark:bg-[#282828]">{skill.skillName}</span>)}</div><div className="mt-3 flex flex-wrap gap-2"><Link href={`/profile?user=${application.applicant?.userId || ""}`} className="rounded-lg border border-slate-200 px-2.5 py-1.5 text-[10px] font-semibold dark:border-[#383838]">View Full Profile</Link>{application.applicationStatus === "PENDING" && <><button type="button" onClick={() => onDecide(application, "ACCEPTED")} className="inline-flex items-center gap-1 rounded-lg bg-[#3ecf8e] px-2.5 py-1.5 text-[10px] font-semibold text-[#042f1a]"><Check className="h-3 w-3" />Accept</button><button type="button" onClick={() => onDecide(application, "REJECTED")} className="rounded-lg border border-rose-300 px-2.5 py-1.5 text-[10px] font-semibold text-rose-600 dark:border-rose-900 dark:text-rose-300">Reject</button></>}</div></div></div></article>) : <Empty text="No applications have been submitted yet." />}</div></aside></div>; }
